INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ತಿಂಗಳು ತುಂಬಾ ಬಿಸಿಲಿದೆ.', 'Ī tingaḷu tumbā bisilide.', 'This month is very sunny/hot.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕಳೆದ ವರ್ಷ ನಾನು ಇಲ್ಲಿ ಇರಲಿಲ್ಲ.', 'Kaḷeda varṣa nānu illi iralilla.', 'Last year I was not here.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಬೆಳಿಗ್ಗೆ ಬೇಗ ಏಳು.', 'Beḷigge bēga ēḷu.', 'Wake up early in the morning.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸಂಜೆ ಆಟ ಆಡೋಣ.', 'Sanje āṭa āḍōṇa.', 'Let''s play in the evening.', 2);
