INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಗುಡಿಯಲ್ಲಿ ಪೂಜೆ ನಡೆಯುತ್ತಿದೆ.', 'Guḍiyalli pūje naḍeyuttide.', 'Worship is happening in the temple.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನ್ನ ಪ್ರಶ್ನೆಗೆ ಉತ್ತರ ಕೊಡು.', 'Nanna praśnege uttara koḍu.', 'Give the answer to my question.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನಿಗೆ ಉತ್ತರ ಗೊತ್ತಿಲ್ಲ.', 'Avanige uttara gottilla.', 'He doesn''t know the answer.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪ್ರೀತಿ ಜೀವನದ ಭಾಗ.', 'Prīti jīvanada bhāga.', 'Love is a part of life.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಯಾರನ್ನೂ ದ್ವೇಷಿಸಬೇಡ.', 'Yārannū dvēṣisabēḍa.', 'Don''t hate anyone.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕೋಪ ಒಳ್ಳೆಯದಲ್ಲ.', 'Kōpa oḷḷeyadalla.', 'Anger is not good.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಶಾಂತಿಯಿಂದ ಇರಿ.', 'Śāntiyinda iri.', 'Be peaceful.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಧೈರ್ಯವಾಗಿ ಮುಂದೆ ಸಾಗು.', 'Dhairyavāgi munde sāgu.', 'Move forward courageously.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಿನಗೆ ಭಯ ಏಕೆ?', 'Ninage bhaya ēke?', 'Why are you afraid?', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಹೂವು ಸುಂದರವಾಗಿದೆ.', 'Ī hūvu sundaravāgide.', 'This flower is beautiful.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳ ಮುಖ ನೋಡಿದೆ.', 'Avaḷa mukha nōḍide.', 'I saw her face.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ದೇಹ ಆರೋಗ್ಯವಾಗಿರಲಿ.', 'Dēha ārōgyavāgirali.', 'May the body be healthy.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನಿಗೆ ಬಹಳ ಶಕ್ತಿ ಇದೆ.', 'Avanige bahaḷa śakti ide.', 'He has a lot of strength.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಜ್ಞಾನ ಶಕ್ತಿ ಇದ್ದಂತೆ.', 'Jñāna śakti iddante.', 'Knowledge is like power.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕನ್ನಡ ಒಂದು ಸುಂದರ ಭಾಷೆ.', 'Kannaḍa ondu sundara bhāṣe.', 'Kannada is a beautiful language.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಮ್ಮ ದೇಶ ಭಾರತ.', 'Namma dēśa Bhārata.', 'Our country is India.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕರ್ನಾಟಕ ಒಂದು ರಾಜ್ಯ.', 'Karnāṭaka ondu rājya.', 'Karnataka is a state.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಜನ ಸಂತೋಷವಾಗಿದ್ದಾರೆ.', 'Jana santoṣavāgiddāre.', 'The people are happy.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳು ಅವನ ಹೆಂಡತಿ.', 'Avaḷu avana henḍati.', 'She is his wife.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನು ಅವಳ ಗಂಡ.', 'Avanu avaḷa gaṇḍa.', 'He is her husband.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮಗು ನಗುತ್ತಿದೆ.', 'Magu naguttide.', 'The child is laughing.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಆ ಹುಡುಗ ಯಾರು?', 'Ā huḍuga yāru?', 'Who is that boy?', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಹುಡುಗಿ ಚೆನ್ನಾಗಿ ಓದುತ್ತಾಳೆ.', 'Ī huḍugi cennāgi ōduttāḷe.', 'This girl studies well.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನು ನನ್ನ ಸ್ನೇಹಿತ.', 'Avanu nanna snēhita.', 'He is my friend.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳು ನನ್ನ ಸ್ನೇಹಿತೆ.', 'Avaḷu nanna snēhite.', 'She is my friend.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಶಿಕ್ಷಕ ಪಾಠ ಹೇಳುತ್ತಿದ್ದಾರೆ.', 'Śikṣaka pāṭha hēḷuttiddāre.', 'The teacher is teaching a lesson.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಶಿಕ್ಷಕಿ ಪ್ರಶ್ನೆ ಕೇಳಿದರು.', 'Śikṣaki praśne kēḷidaru.', 'The teacher (female) asked a question.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ವಿದ್ಯಾರ್ಥಿ ಗಮನವಿಟ್ಟು ಕೇಳುತ್ತಿದ್ದಾನೆ.', 'Vidyārthi gamanaviṭṭu kēḷuttiddāne.', 'The student is listening attentively.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ವೈದ್ಯರು ಆಸ್ಪತ್ರೆಯಲ್ಲಿದ್ದಾರೆ.', 'Vaidyaru āspatreyalliddāre.', 'The doctor is in the hospital.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಆಹಾರ ರುಚಿಕರವಾಗಿದೆ.', 'Āhāra rucikaravāgide.', 'The food is tasty.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ತರಕಾರಿ ಆರೋಗ್ಯಕ್ಕೆ ಒಳ್ಳೆಯದು.', 'Tarakāri ārōgyakke oḷḷeyadu.', 'Vegetables are good for health.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅಕ್ಕಿ ಅಂಗಡಿಯಲ್ಲಿ ಸಿಗುತ್ತದೆ.', 'Akki angaḍiyalli siguttade.', 'Rice (uncooked) is available in the shop.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅನ್ನ ಬಿಸಿಯಾಗಿದೆ.', 'Anna bisiyāgide.', 'The rice (cooked) is hot.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಹಣ್ಣು ಸಿಹಿಯಾಗಿದೆ.', 'Ī haṇṇu sihiyāgide.', 'This fruit is sweet.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಿಂಬೆ ಹಣ್ಣು ಹುಳಿಯಾಗಿದೆ.', 'Nimbe haṇṇu huḷiyāgide.', 'The lemon is sour.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಊಟ ತುಂಬಾ ಖಾರವಾಗಿತ್ತು.', 'Ūṭa tumbā khāravāgittu.', 'The meal was very spicy.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನಗೆ ಸ್ವಲ್ಪ ಉಪ್ಪು ಕೊಡು.', 'Nanage svalpa uppu koḍu.', 'Give me a little salt.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಸೊಪ್ಪು ಕಹಿಯಾಗಿದೆ.', 'Ī soppu kahiyāgide.', 'These greens are bitter.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನಗೆ ಹಸಿವಾಗಿದೆ.', 'Nanage hasivāgide.', 'I am hungry.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನಿಗೆ ಬಾಯಾರಿಕೆಯಾಗಿದೆ.', 'Avanige bāyārikeyāgide.', 'He is thirsty.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ರಾತ್ರಿ ಬೇಗ ನಿದ್ರೆ ಮಾಡು.', 'Rātri bēga nidre māḍu.', 'Sleep early at night.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇಲ್ಲಿ ಹತ್ತಿರ ಬಾ.', 'Illi hattira bā.', 'Come near here.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅಲ್ಲಿ ದೂರ ಹೋಗು.', 'Alli dūra hōgu.', 'Go far there.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮನೆಯ ಒಳಗೆ ಬಾ.', 'Maneya oḷage bā.', 'Come inside the house.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮನೆಯ ಹೊರಗೆ ಹೋಗು.', 'Maneya horage hōgu.', 'Go outside the house.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕಾರು ಮನೆಯ ಮುಂದೆ ಇದೆ.', 'Kāru maneya munde ide.', 'The car is in front of the house.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮರ ಮನೆಯ ಹಿಂದೆ ಇದೆ.', 'Mara maneya hinde ide.', 'The tree is behind the house.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನು ನನ್ನ ಪಕ್ಕ ಕುಳಿತಿದ್ದಾನೆ.', 'Avanu nanna pakka kuḷitiddāne.', 'He is sitting beside me.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ರಸ್ತೆಯ ಮಧ್ಯ ನಡೆಯಬೇಡ.', 'Rasteya madhya naḍeyabēḍa.', 'Don''t walk in the middle of the road.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮನೆಯ ಸುತ್ತ ಗಿಡಗಳಿವೆ.', 'Maneya sutta giḍagaḷive.', 'There are plants around the house.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನೇರವಾಗಿ ಹೋಗು.', 'Nēravāgi hōgu.', 'Go straight.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಬಲಕ್ಕೆ ತಿರುಗು.', 'Balakke tirugu.', 'Turn right.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಎಡಕ್ಕೆ ನೋಡು.', 'Eḍakke nōḍu.', 'Look left.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳಿಗೆ ತುಂಬಾ ಕೆಲಸ ಇದೆ.', 'Avaḷige tumbā kelasa ide.', 'She has a lot of work.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನಗೆ ಸ್ವಲ್ಪ ನೀರು ಬೇಕು.', 'Nanage svalpa nīru bēku.', 'I need a little water.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇನ್ನೂ ಹೆಚ್ಚು ಅನ್ನ ಹಾಕು.', 'Innū heccu anna hāku.', 'Serve more rice.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಶಬ್ದ ಕಡಿಮೆ ಮಾಡು.', 'Śabda kaḍime māḍu.', 'Reduce the noise.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಕೆಲಸ ಸುಲಭವಾಗಿದೆ.', 'Ī kelasa sulabhavāgide.', 'This work is easy.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಆ ಪರೀಕ್ಷೆ ಕಷ್ಟವಾಗಿತ್ತು.', 'Ā parīkṣe kaṣṭavāgittu.', 'That exam was difficult.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನೀರು ಶುದ್ಧವಾಗಿದೆ.', 'Nīru śuddhavāgide.', 'The water is pure.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಆನೆ ದೊಡ್ಡ ಪ್ರಾಣಿ.', 'Āne doḍḍa prāṇi.', 'Elephant is a big animal.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಗಿಳಿ ಹಸಿರು ಪಕ್ಷಿ.', 'Giḷi hasiru pakṣi.', 'Parrot is a green bird.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮೀನು ನೀರಿನಲ್ಲಿ ವಾಸಿಸುತ್ತದೆ.', 'Mīnu nīrinalli vāsisuttade.', 'Fish lives in water.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹಾವು ಹುತ್ತದಲ್ಲಿದೆ.', 'Hāvu huttadallide.', 'The snake is in the anthill.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕುದುರೆ ವೇಗವಾಗಿ ಓಡುತ್ತದೆ.', 'Kudure vēgavāgi ōḍuttade.', 'The horse runs fast.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹಸು ಹಾಲು ಕೊಡುತ್ತದೆ.', 'Hasu hālu koḍuttade.', 'The cow gives milk.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇರುವೆ ಸಾಲಿನಲ್ಲಿ ಹೋಗುತ್ತಿದೆ.', 'Iruve sālinalli hōguttide.', 'The ant is going in a line.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾನು ಹೇಗೆ ಬರಲಿ?', 'Nānu hēge barali?', 'How should I come?', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನೀನು ಯಾಕೆ ಅಳುತ್ತಿರುವೆ?', 'Nīnu yāke aḷuttiruve?', 'Why are you crying?', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವರು ಯಾವಾಗ ಬರುತ್ತಾರೆ?', 'Avaru yāvāga baruttāre?', 'When will they come?', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಪುಸ್ತಕದ ಬೆಲೆ ಎಷ್ಟು?', 'Ī pustakada bele eṣṭu?', 'How much is the price of this book?', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅದು ದೊಡ್ಡದು, ಇದು ಚಿಕ್ಕದು.', 'Adu doḍḍadu, idu cikkadu.', 'That is big, this is small.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪೆನ್ ಮೇಜಿನ ಕೆಳಗೆ ಬಿದ್ದಿದೆ.', 'Pen mējina keḷage biddide.', 'The pen has fallen under the table.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಗಂಟೆ ಶಬ್ದ ಕೇಳಿಸಿತು.', 'Ganṭe śabda kēḷisitu.', 'The sound of the bell was heard.', 2);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಶಿಕ್ಷಣ ಬಹುಮುಖ್ಯವಾಗಿದೆ.', 'Śikṣaṇa bahumukhyavāgide.', 'Education is very important.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾನು ವಿದ್ಯಾಲಯಕ್ಕೆ ಹೋಗುತ್ತೇನೆ.', 'Nānu vidyālayakke hōguttēne.', 'I go to school.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ವಿಮಾನ ವೇಗವಾಗಿ ಚಲಿಸುತ್ತದೆ.', 'Vimāna vēgavāgi calisuttade.', 'The airplane moves fast.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ರೈಲು ನಿಲ್ದಾಣಕ್ಕೆ ಬಂದಿತು.', 'Railu nildāṇakke banditu.', 'The train arrived at the station.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹಡಗು ಸಮುದ್ರದಲ್ಲಿ ಪ್ರಯಾಣಿಸುತ್ತದೆ.', 'Haḍagu samudradalli prayāṇisuttade.', 'The ship travels on the sea.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸಮುದ್ರ ತೀರದಲ್ಲಿ ಅಲೆಗಳಿವೆ.', 'Samudra tīradalli alegaḷive.', 'There are waves on the seashore.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನ್ನ ಪ್ರಯಾಣ ಸುಖಕರವಾಗಿತ್ತು.', 'Nanna prayāṇa sukhakaravāgittu.', 'My journey was comfortable.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಗ್ರಾಮ ಜೀವನ ಶಾಂತವಾಗಿರುತ್ತದೆ.', 'Grāma jīvana śāntavāgiruttade.', 'Village life is peaceful.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಕ್ಷೆ ದಾರಿ ತೋರಿಸುತ್ತದೆ.', 'Nakṣe dāri tōrisuttade.', 'The map shows the way.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸರ್ಕಾರ ಜನರಿಗಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ.', 'Sarkāra janarigāgi kelasa māḍuttade.', 'The government works for the people.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕಾನೂನು ಎಲ್ಲರಿಗೂ ಸಮಾನ.', 'Kānūnu ellarigū samāna.', 'The law is equal for everyone.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನ್ಯಾಯ ಎಲ್ಲರಿಗೂ ಸಿಗಬೇಕು.', 'Nyāya ellarigū sigabēku.', 'Justice should be available to everyone.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅಪರಾಧ ಮಾಡುವುದು ತಪ್ಪು.', 'Aparādha māḍuvudu tappu.', 'Committing a crime is wrong.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ತಪ್ಪು ಮಾಡಿದರೆ ಶಿಕ್ಷೆ ಆಗುತ್ತದೆ.', 'Tappu māḍidare śikṣe āguttade.', 'If you do wrong, you will be punished.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಭಾರತಕ್ಕೆ ೧೯೪೭ ರಲ್ಲಿ ಸ್ವಾತಂತ್ರ್ಯ ಸಿಕ್ಕಿತು.', 'Bhāratakke 1947 ralli svātantrya sikkitu.', 'India got independence in 1947.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸ್ವಾತಂತ್ರ್ಯಕ್ಕಾಗಿ ಅನೇಕರು ಹೋರಾಟ ಮಾಡಿದರು.', 'Svātantryakkāgi anēkaru hōrāṭa māḍidaru.', 'Many people struggled for freedom.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾವು ಸಮಾಜದಲ್ಲಿ ಒಟ್ಟಿಗೆ ಬಾಳುತ್ತೇವೆ.', 'Nāvu samājadalli oṭṭige bāḷuttēve.', 'We live together in society.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಭಾರತೀಯ ಸಂಸ್ಕೃತಿ ವೈವಿಧ್ಯಮಯವಾಗಿದೆ.', 'Bhāratīya saṁskṛti vaividhyamayavāgide.', 'Indian culture is diverse.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹಬ್ಬಗಳು ನಮ್ಮ ಪರಂಪರೆಯ ಭಾಗ.', 'Habbagaḷu namma parampareya bhāga.', 'Festivals are part of our tradition.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಧರ್ಮ ಸನ್ಮಾರ್ಗವನ್ನು ತೋರಿಸುತ್ತದೆ.', 'Dharma sanmārgavannu tōrisuttade.', 'Religion shows the right path.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನಗೆ ನಿನ್ನ ಮೇಲೆ ನಂಬಿಕೆ ಇದೆ.', 'Nanage ninna mēle nambike ide.', 'I have trust in you.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ವಿಜ್ಞಾನ ಪ್ರಗತಿಗೆ ಕಾರಣವಾಗಿದೆ.', 'Vijñāna pragatige kāraṇavāgide.', 'Science is the reason for progress.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ತಂತ್ರಜ್ಞಾನ ನಮ್ಮ ಜೀವನವನ್ನು ಸುಲಭಗೊಳಿಸಿದೆ.', 'Tantrajñāna namma jīvanavannu sulabhagoḷiside.', 'Technology has made our lives easier.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾವು ಪರಿಸರವನ್ನು ರಕ್ಷಿಸಬೇಕು.', 'Nāvu parisaravannu rakṣisabēku.', 'We must protect the environment.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಭವಿಷ್ಯದ ಬಗ್ಗೆ ಯೋಚಿಸು.', 'Bhaviṣyada bagge yōcisu.', 'Think about the future.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಭೂತಕಾಲವನ್ನು ಮರೆಯಬಾರದು.', 'Bhūtakālavannu mareyabāradu.', 'One should not forget the past.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ವರ್ತಮಾನದಲ್ಲಿ ಜೀವಿಸು.', 'Vartamānadalli jīvisu.', 'Live in the present.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕಲೆ ಮನಸ್ಸಿಗೆ ಆನಂದ ನೀಡುತ್ತದೆ.', 'Kale manassige ānanda nīḍuttade.', 'Art gives joy to the mind.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸಂಗೀತ ಕೇಳಲು ನನಗೆ ಇಷ್ಟ.', 'Sangīta kēḷalu nanage iṣṭa.', 'I like to listen to music.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳು ಚೆನ್ನಾಗಿ ನೃತ್ಯ ಮಾಡುತ್ತಾಳೆ.', 'Avaḷu cennāgi nṛtya māḍuttāḷe.', 'She dances well.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾವು ನಿನ್ನೆ ನಾಟಕ ನೋಡಿದೆವು.', 'Nāvu ninne nāṭaka nōḍidevu.', 'We watched a play yesterday.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಚಿತ್ರ ಬಹಳ ಸುಂದರವಾಗಿದೆ.', 'Ī citra bahaḷa sundaravāgide.', 'This picture is very beautiful.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕನ್ನಡ ಸಾಹಿತ್ಯ ಶ್ರೀಮಂತವಾಗಿದೆ.', 'Kannaḍa sāhitya śrīmantavāgide.', 'Kannada literature is rich.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವರು ಒಂದು ಕವಿತೆ ಬರೆದರು.', 'Avaru ondu kavite baredaru.', 'He/She wrote a poem.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅಜ್ಜಿ ನಮಗೆ ಕಥೆ ಹೇಳಿದರು.', 'Ajji namage kathe hēḷidaru.', 'Grandmother told us a story.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಲೇಖನ ಉಪಯುಕ್ತವಾಗಿದೆ.', 'Ī lēkhana upayuktavāgide.', 'This article is useful.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನು ವ್ಯಾಪಾರ ಮಾಡುತ್ತಾನೆ.', 'Avanu vyāpāra māḍuttāne.', 'He does business.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳಿಗೆ ಒಳ್ಳೆಯ ಉದ್ಯೋಗ ಸಿಕ್ಕಿದೆ.', 'Avaḷige oḷḷeya udyōga sikkide.', 'She has got a good job.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕೃಷಿ ಭಾರತದ ಆರ್ಥಿಕತೆಗೆ ಮುಖ್ಯ.', 'Kṛṣi bhāratada ārthikatege mukhya.', 'Agriculture is important to India''s economy.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ರೈತ ಹೊಲದಲ್ಲಿ ಕೆಲಸ ಮಾಡುತ್ತಾನೆ.', 'Raita holadalli kelasa māḍuttāne.', 'The farmer works in the field.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಭೂಮಿ ಫಲವತ್ತಾಗಿದೆ.', 'Bhūmi phalavattāgide.', 'The land is fertile.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ವರ್ಷ ಬೆಳೆ ಚೆನ್ನಾಗಿ ಬಂದಿದೆ.', 'Ī varṣa beḷe cennāgi bandide.', 'The crop has come well this year.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಗಿಡಗಳಿಗೆ ಪ್ರತಿದಿನ ನೀರುಹಾಕು.', 'Giḍagaḷige pratidina nīruhāku.', 'Water the plants daily.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅಮ್ಮ ಅಡುಗೆ ಮಾಡುತ್ತಿದ್ದಾರೆ.', 'Amma aḍuge māḍuttiddāre.', 'Mother is cooking.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪಾತ್ರೆಯನ್ನು ಸ್ವಚ್ಛವಾಗಿ ತೊಳೆ.', 'Pātreyannu svacchavāgi toḷe.', 'Wash the vessel cleanly.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಚಮಚದಿಂದ ತಿನ್ನು.', 'Camacadinda tinnu.', 'Eat with a spoon.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ತಟ್ಟೆಯಲ್ಲಿ ಊಟ ಬಡಿಸು.', 'Taṭṭeyalli ūṭa baḍisu.', 'Serve the meal on the plate.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಲೋಟದಲ್ಲಿ ನೀರು ತುಂಬಿಸು.', 'Lōṭadalli nīru tumbisu.', 'Fill water in the glass.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಿಜವಾದ ಸ್ನೇಹ ಅಮೂಲ್ಯ.', 'Nijavāda snēha amūlya.', 'True friendship is precious.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವರ ಸಂಬಂಧ ಗಟ್ಟಿಯಾಗಿದೆ.', 'Avara sambandha gaṭṭiyāgide.', 'Their relationship is strong.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನ್ನ ಕುಟುಂಬ ದೊಡ್ಡದು.', 'Nanna kuṭumba doḍḍadu.', 'My family is large.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನೆರೆಹೊರೆಯವರೊಂದಿಗೆ ಚೆನ್ನಾಗಿರು.', 'Nerehoreyavarondige cennāgiru.', 'Be good with neighbors.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನು ನನಗೆ ಸಹಾಯ ಮಾಡಿದನು.', 'Avanu nanage sahāya māḍidanu.', 'He helped me.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾನು ನಿನಗೆ ಉಡುಗೊರೆ ತಂದಿದ್ದೇನೆ.', 'Nānu ninage uḍugore tandiddēne.', 'I have brought a gift for you.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾವು ದೀಪಾವಳಿ ಹಬ್ಬ ಆಚರಿಸುತ್ತೇವೆ.', 'Nāvu dīpāvaḷi habba ācarisuttēve.', 'We celebrate the Diwali festival.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಆಚರಣೆ ಸಂಭ್ರಮದಿಂದ ಕೂಡಿತ್ತು.', 'Ācaraṇe sambhramadinda kūḍittu.', 'The celebration was full of joy.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಶಾಲೆಯಲ್ಲಿ ವಾರ್ಷಿಕ ಕಾರ್ಯಕ್ರಮವಿದೆ.', 'Śāleyalli vārṣika kāryakramavide.', 'There is an annual program at the school.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಮದುವೆಗೆ ಆಹ್ವಾನ ಬಂದಿದೆ.', 'Maduvēge āhvāna bandide.', 'An invitation for the wedding has come.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾವು ಪ್ರತಿದಿನ ಪ್ರಾರ್ಥನೆ ಮಾಡುತ್ತೇವೆ.', 'Nāvu pratidina prārthane māḍuttēve.', 'We pray every day.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹಿರಿಯರ ಆಶೀರ್ವಾದ ಪಡೆಯಬೇಕು.', 'Hiriyara āśīrvāda paḍeyabēku.', 'One should get blessings from elders.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನು ತುಂಬಾ ಸಂತೋಷವಾಗಿದ್ದನು.', 'Avanu tumbā santoṣavāgiddanu.', 'He was very happy.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ದುಃಖ ಪಡಬೇಡ, ಎಲ್ಲವೂ ಸರಿಹೋಗುತ್ತದೆ.', 'Duḥkha paḍabēḍa, ellavū sarihōguttade.', 'Don''t be sad, everything will be alright.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವನಿಗೆ ಆಶ್ಚರ್ಯವಾಯಿತು.', 'Avanige āścaryavāyitu.', 'He was surprised.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಯಾವುದಕ್ಕೂ ಚಿಂತೆ ಮಾಡಬೇಡ.', 'Yāvudakkū cinte māḍabēḍa.', 'Don''t worry about anything.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳ ನಗುಮುಖ ಎಲ್ಲರಿಗೂ ಇಷ್ಟ.', 'Avaḷa nagumukha ellarigū iṣṭa.', 'Everyone likes her smiling face.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾನು ನಿನ್ನೆ ಒಂದು ಕನಸು ಕಂಡೆ.', 'Nānu ninne ondu kanasu kaṇḍe.', 'I saw a dream yesterday.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹಳೆಯ ನೆನಪುಗಳು ಮರುಕಳಿಸಿದವು.', 'Haḷeya nenapugaḷu marukaḷisidavu.', 'Old memories recurred.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಒಳ್ಳೆಯ ಯೋಚನೆಗಳನ್ನು ಮಾಡು.', 'Oḷḷeya yōcanegaḷannu māḍu.', 'Think good thoughts.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾವು ಸರಿಯಾದ ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳಬೇಕು.', 'Nāvu sariyāda nirdhāra tegedukoḷḷabēku.', 'We must take the right decision.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇದಕ್ಕೆ ಕಾರಣ ಏನು?', 'Idakke kāraṇa ēnu?', 'What is the reason for this?', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪ್ರತಿ ಕ್ರಿಯೆಗೆ ಒಂದು ಪರಿಣಾಮ ಇರುತ್ತದೆ.', 'Prati kriyege ondu pariṇāma iruttade.', 'Every action has a result.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಜಗತ್ತಿನಲ್ಲಿ ಬದಲಾವಣೆ ನಿರಂತರ.', 'Jagattinalli badalāvaṇe nirantara.', 'Change is constant in the world.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ದೇಶದ ಅಭಿವೃದ್ಧಿ ಮುಖ್ಯ.', 'Dēśada abhivṛddhi mukhya.', 'The country''s development is important.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪ್ರತಿಯೊಂದು ಸಮಸ್ಯೆಗೆ ಪರಿಹಾರವಿದೆ.', 'Pratiyondu samasyege parihāravide.', 'There is a solution to every problem.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಮಗೆ ಒಳ್ಳೆಯ ಅವಕಾಶ ಸಿಕ್ಕಿದೆ.', 'Namage oḷḷeya avakāśa sikkide.', 'We have got a good opportunity.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪ್ರಯತ್ನ ಪಟ್ಟರೆ ಯಶಸ್ಸು ಖಂಡಿತ.', 'Prayatna paṭṭare yaśassu khaṇḍita.', 'If you make an effort, success is definite.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸೋಲನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಲು ಕಲಿ.', 'Sōlannu oppikoḷḷalu kali.', 'Learn to accept defeat.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನ್ನ ಗುರಿ ವೈದ್ಯನಾಗುವುದು.', 'Nanna guri vaidyanāguvudu.', 'My goal is to become a doctor.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಸರಿಯಾದ ಮಾರ್ಗವನ್ನು ಅನುಸರಿಸು.', 'Sariyāda mārgavannu anusarisu.', 'Follow the right path.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳಿಗೆ ವಿದೇಶಕ್ಕೆ ಹೋಗುವ ಆಸೆ.', 'Avaḷige vidēśakke hōguva āse.', 'She desires to go abroad.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಪ್ರಯಾಣದಿಂದ ಹೊಸ ಅನುಭವ ಸಿಗುತ್ತದೆ.', 'Prayāṇadinda hosa anubhava siguttade.', 'One gets new experiences from traveling.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇದು ಪ್ರಮುಖ ವಿಷಯ.', 'Idu pramukha viṣaya.', 'This is an important matter.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇದು ಸಾಮಾನ್ಯ ಸಂಗತಿ.', 'Idu sāmānya sangati.', 'This is a common thing.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇಂದು ವಿಶೇಷ ದಿನ.', 'Indu viśēṣa dina.', 'Today is a special day.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇಲ್ಲಿ ವಿವಿಧ ರೀತಿಯ ಹಣ್ಣುಗಳಿವೆ.', 'Illi vividha rītiya haṇṇugaḷive.', 'There are various types of fruits here.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಒಂದು ಉದಾಹರಣೆ ಕೊಡು.', 'Ondu udāharaṇe koḍu.', 'Give an example.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ದಯವಿಟ್ಟು ನನಗೆ ಮಾಹಿತಿ ನೀಡಿ.', 'Dayaviṭṭu nanage māhiti nīḍi.', 'Please give me information.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಇಂದಿನ ಮುಖ್ಯ ಸುದ್ದಿ ಏನು?', 'Indina mukhya suddi ēnu?', 'What is today''s main news?', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನಾನು ಪ್ರತಿದಿನ ಪತ್ರಿಕೆ ಓದುತ್ತೇನೆ.', 'Nānu pratidina patrike ōduttēne.', 'I read the newspaper every day.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ದೂರದರ್ಶನದಲ್ಲಿ ಚಲನಚಿತ್ರ ನೋಡಿದೆ.', 'Dūradarśanadalli calanacitra nōḍide.', 'I watched a movie on television.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಅವಳ ದನಿ ಮಧುರವಾಗಿದೆ.', 'Avaḷa dani madhuravāgide.', 'Her voice is sweet.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಹೊರಗಿನಿಂದ ಶಬ್ದ ಬರುತ್ತಿದೆ.', 'Horagininda śabda baruttide.', 'Noise is coming from outside.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕೋಣೆಯಲ್ಲಿ ಬೆಳಕು ಕಡಿಮೆಯಿದೆ.', 'Kōṇeyalli beḷaku kaḍimeyide.', 'The light in the room is low.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಕತ್ತಲೆಯಲ್ಲಿ ನಡೆಯುವುದು ಕಷ್ಟ.', 'Kattaleyalli naḍeyuvudu kaṣṭa.', 'It is difficult to walk in the dark.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಚಂದ್ರನ ಆಕಾರ ಬದಲಾಗುತ್ತದೆ.', 'Candrana ākāra badalāguttade.', 'The shape of the moon changes.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಪೆಟ್ಟಿಗೆಯ ಗಾತ್ರ ದೊಡ್ಡದಿದೆ.', 'Ī peṭṭigeya gātra doḍḍadide.', 'The size of this box is big.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಆ ಮರ ತುಂಬಾ ಎತ್ತರವಿದೆ.', 'Ā mara tumbā ettaravide.', 'That tree is very tall.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ನನ್ನ ತೂಕ ೬೦ ಕೆಜಿ ಇದೆ.', 'Nanna tūka 60 keji ide.', 'My weight is 60 kg.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಹಗ್ಗದ ಉದ್ದ ಎಷ್ಟು?', 'Ī haggada udda eṣṭu?', 'What is the length of this rope?', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ರಸ್ತೆಯ ಅಗಲ ಸಾಕಷ್ಟಿದೆ.', 'Rasteya agala sākṣṭide.', 'The width of the road is sufficient.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಬಾವಿಯ ಆಳ ಹೆಚ್ಚಿದೆ.', 'Bāviya āḷa heccide.', 'The depth of the well is more.', 3);
INSERT INTO sentences (kannada_sentence, transliteration, english_translation, level) VALUES ('ಈ ಎರಡರ ನಡುವೆ ವ್ಯತ್ಯಾಸವಿದೆ.', 'Ī eraḍara naḍuve vyatyāsavide.', 'There is a difference between these two.', 3);
